-- Match Report → Nexus: GW001–GW010 on their configured databases.
-- Canonical identity: game_world_id + sm_fixture_id. Source rows remain unchanged.
-- A missing report date can be resolved only by its exact fixture in Results.

-- Database target: gold
UPDATE `IMC Site Match Report` s JOIN `GW002_IMC Match Report` m ON s.game_world_id=m.game_world_id AND s.sm_fixture_id=m.sm_fixture_id SET s.source_key=SHA2(CONCAT('IMC Match Report|',m.`game_world_id`,'|',m.`sm_fixture_id`),256) WHERE m.game_world_id='GW002';

